export class LaunchTaskTool extends BaseDeclarativeTool<
  LaunchTaskParams,
  ToolResult
> {
  constructor(private readonly config?: Config) {
    super(
      "launch_task",
      "Launch Task",
      launchTaskToolDescription,
      Kind.Other,
      launchTaskToolSchemaData.parametersJsonSchema,
      true, // isOutputMarkdown
      false, // canUpdateOutput
    );
  }

  protected override createInvocation(
    params: LaunchTaskParams,
  ): LaunchTaskInvocation {
    const configuredMode = process.env["LOWCAL_SCHEDULER_DEFAULT_MODE"];
    const defaultExecutionMode: JobExecutionMode =
      configuredMode === "zellij_tab" ? "zellij_tab" : "headless";
    return new LaunchTaskInvocation(
      params,
      this.config?.getSessionId(),
      defaultExecutionMode,
    );
  }
}
